CREATE OR REPLACE FUNCTION inserer_conducteur(
  p_civilite IN VARCHAR2,
  p_nom IN VARCHAR2,
  p_prenom IN VARCHAR2,
  p_permis_types IN SYS.ODCIVARCHAR2LIST  -- liste de types
) RETURN NUMBER
IS
  v_id_cond NUMBER;
BEGIN
  IF p_civilite NOT IN ('M', 'Mme', 'Mlle') THEN
    RAISE_APPLICATION_ERROR(-20010, 'Civilité invalide');
  END IF;

  INSERT INTO Conducteur(civilite, nom, prenom)
  VALUES (p_civilite, p_nom, p_prenom)
  RETURNING N INTO v_id_cond;

  FOR i IN 1..p_permis_types.COUNT LOOP
    INSERT INTO Permis(type) VALUES (p_permis_types(i));
    INSERT INTO titulaire(N_cond, N_permis) VALUES (v_id_cond, Permis_seq.CURRVAL);
  END LOOP;

  RETURN v_id_cond;
END;

CREATE OR REPLACE TRIGGER trig_vehicule_libre
BEFORE INSERT ON louer
FOR EACH ROW
DECLARE
  v_nb NUMBER;
BEGIN
  SELECT COUNT(*) INTO v_nb
  FROM louer
  WHERE N_vehic = :new.N_vehic
    AND (debut <= :new.fin AND fin >= :new.debut);

  IF v_nb > 0 THEN
    RAISE_APPLICATION_ERROR(-20020, 'Véhicule déjà loué sur cette période');
  END IF;
END;

CREATE OR REPLACE TRIGGER trig_permis_compatible
BEFORE INSERT OR UPDATE ON louer
FOR EACH ROW
DECLARE
  v_count NUMBER;
BEGIN
  SELECT COUNT(*) INTO v_count
  FROM necessiter n
  WHERE n.N_vehic = :new.N_vehic
    AND NOT EXISTS (
      SELECT 1
      FROM titulaire t
      JOIN Permis p ON p.N = t.N_permis
      WHERE t.N_cond = :new.N_cond
        AND p.type = n.type_permis
    );

  IF v_count > 0 THEN
    RAISE_APPLICATION_ERROR(-20030, 'Le conducteur n''a pas tous les permis nécessaires');
  END IF;
END;

-- Procédure récursive : on construit la chaîne de vols via une procédure interne explore.
-- Pour rester compatible PL/SQL (récursion sur procédure stockée), on déclare explore en avant.

CREATE OR REPLACE PROCEDURE tour_du_monde(
  p_depart  IN VOL.Ville_depart%TYPE,
  p_min     IN NUMBER,
  p_max     IN NUMBER
)
IS
  TYPE t_chemin IS TABLE OF NUMBER INDEX BY PLS_INTEGER;

  PROCEDURE explore(
    p_current_city IN VOL.Ville_depart%TYPE,
    p_depth        IN NUMBER,
    p_path         IN OUT t_chemin
  )
  IS
  BEGIN
    -- Si on revient au départ et qu'on a fait assez d'escales : tour valide
    IF p_current_city = p_depart AND p_depth BETWEEN p_min AND p_max AND p_depth > 0 THEN
      DBMS_OUTPUT.PUT_LINE('--- Tour du monde proposé ---');
      FOR i IN 1..p_path.COUNT LOOP
        FOR v IN (SELECT Numvol, Ville_depart, Ville_arrivee
                  FROM VOL WHERE Numvol = p_path(i)) LOOP
          DBMS_OUTPUT.PUT_LINE('  Vol ' || v.Numvol || ' : ' || v.Ville_depart || ' -> ' || v.Ville_arrivee);
        END LOOP;
      END LOOP;
      RETURN;
    END IF;

    -- Si on a dépassé le max d'escales, on arrête
    IF p_depth >= p_max THEN RETURN; END IF;

    -- Sinon, on explore chaque vol partant de la ville courante
    FOR v IN (SELECT Numvol, Ville_arrivee FROM VOL WHERE Ville_depart = p_current_city) LOOP
      p_path(p_path.COUNT + 1) := v.Numvol;
      explore(v.Ville_arrivee, p_depth + 1, p_path);
      p_path.DELETE(p_path.COUNT);  -- backtrack
    END LOOP;
  END;

  v_path t_chemin;
BEGIN
  explore(p_depart, 0, v_path);
END;
